import struct
import sys

import wgpu

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
};

@group(0) @binding(0) var<uniform> p: Params;
// [0] inside, [1..8] bins, [9] sum of escape times of escaped points
@group(0) @binding(1) var<storage, read_write> out: array<atomic<u32>, 10>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    if (gid.x >= p.width || gid.y >= p.height) {
        return;
    }
    let cx = p.x_min + (f32(gid.x) + 0.5) * p.dx;
    let cy = p.y_min + (f32(gid.y) + 0.5) * p.dy;
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    while (n < p.limit && zx * zx + zy * zy <= 4.0) {
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    if (n == p.limit) {
        atomicAdd(&out[0], 1u);
    } else {
        let b = min((8u * n) / p.limit, 7u);
        atomicAdd(&out[1u + b], 1u);
        atomicAdd(&out[9], n);
    }
}
"""


def main():
    with open(sys.argv[1]) as f:
        tok = f.read().split()
    width, height, limit = int(tok[0]), int(tok[1]), int(tok[2])
    x_min, x_max, y_min, y_max = (float(t) for t in tok[3:7])
    dx = (x_max - x_min) / width
    dy = (y_max - y_min) / height

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    params = struct.pack("<4I4f", width, height, limit, 0, x_min, dx, y_min, dy)
    pbuf = device.create_buffer_with_data(data=params, usage=wgpu.BufferUsage.UNIFORM)
    obuf = device.create_buffer(
        size=40,
        usage=wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST,
    )
    device.queue.write_buffer(obuf, 0, bytes(40))

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": pbuf, "offset": 0, "size": 32}},
            {"binding": 1, "resource": {"buffer": obuf, "offset": 0, "size": 40}},
        ],
    )

    enc = device.create_command_encoder()
    cp = enc.begin_compute_pass()
    cp.set_pipeline(pipeline)
    cp.set_bind_group(0, bind)
    cp.dispatch_workgroups((width + 7) // 8, (height + 7) // 8, 1)
    cp.end()
    device.queue.submit([enc.finish()])

    res = struct.unpack("<10I", bytes(device.queue.read_buffer(obuf)))
    inside, bins, total = res[0], res[1:9], res[9]
    escaped = sum(bins)
    mean = total / escaped if escaped else 0.0

    out = [f"INSIDE {inside}"]
    out += [f"BIN {i} {c}" for i, c in enumerate(bins)]
    out.append(f"MEAN {mean:.3f}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
